def prose(value):
    value=re.sub(r'([А-Яа-яЁёA-Za-z])(\d)',r'\1 \2',value)
    value=re.sub(r'(\d)([А-Яа-яЁёA-Za-z])',r'\1 \2',value)
    value=re.sub(r'([А-Яа-яЁё])([A-Za-z])',r'\1 \2',value)
    value=re.sub(r'([A-Za-z])([А-Яа-яЁё])',r'\1 \2',value)
    value=re.sub(r'([:;·])(?=\S)',r'\1 ',value)
    value=re.sub(r'(\d{1,2}): (\d{2})\b',r'\1:\2',value)
    value=re.sub(r',(?=[А-Яа-яЁёA-Za-z])',', ',value)
    value=re.sub(r'(?<=\S)\+(?=\S)',' + ',value)
    replacements={'письменныйдопуск':'письменный допуск','младшееисключение':'младшее исключение','Проверитьаккаунткоманды':'Проверить аккаунт команды','обычнаяоткрытая':'обычная открытая','минутнуюсамостоятельную':'минутную самостоятельную','возможная общая':'возможная общая','обоимв':'обоим в','Местныйсостав':'Местный состав','демонстрационныйфестиваль':'демонстрационный фестиваль','медалькаждому':'медаль каждому','отдельнаякоманда':'отдельная команда','датысобытия':'даты события','включаетнедостающую':'включает недостающую','иполный':'и полный','семейнаясмета':'семейная смета','полнаяценым':'полная цена m','FoundersExplore':'Founders Explore','SPIKEPrime':'SPIKE Prime','RobotifestUCR':'Robotifest UCR','PuertoVallarta':'Puerto Vallarta','предварительнаядокументация':'предварительная документация','локальныйсостав':'локальный состав','возрастноеDOBокно':'возрастное DOB окно','структурированнаяцена':'структурированная цена','бесплатныйвход':'бесплатный вход','местныйокончательный':'местный окончательный','провереннаясемейнаясмета':'проверенная семейная смета','совместныйсемейный':'совместный семейный','потоки пока':'потоки пока','самостоятельностьмладшего':'самостоятельность младшего','Самостоятельностьмладшего':'Самостоятельность младшего','PDF p ':'PDF p','датасобытия':'дата события','способи':'способ и','реальныйрезультат':'реальный результат','навыки':'навыки'}
    replacements.update({'LEGOSecundaria':'LEGO Secundaria','провереннаясемейная':'проверенная семейная','EV 3':'EV3','приDOB':'при DOB','словодокументации':'слово документации','Не включаетнедостающую':'Не включает недостающую','регулярнаякоманда':'регулярная команда','сохранивсовместный':'сохранив совместный','основнаямодель':'основная модель','условия/полныйсчёт':'условия / полный счёт','входит 1регистрация':'входит 1 регистрация'})
    for a,b in replacements.items():value=value.replace(a,b)
    return value

